package com.contextgraph.security; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.*; @Service public class JwtService { private final SecretKey key; private final long exp; public JwtService(@Value("${app.jwt.secret}")String secret,@Value("${app.jwt.expiration-ms}")long exp){if(secret.length()<32)throw new IllegalArgumentException("JWT_SECRET must be at least 32 characters");key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.exp=exp;} public String generate(String subject){Date n=new Date();return Jwts.builder().subject(subject).issuedAt(n).expiration(new Date(n.getTime()+exp)).signWith(key).compact();} public String subject(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} public boolean valid(String token){try{subject(token);return true;}catch(Exception e){return false;}}}